<script lang="ts">
  import {onMount} from 'svelte';
  import {call,native,onEvent} from '../lib/api';
  import {t,locale,formatNumber} from '../lib/i18n';
  import {parseContentRef} from '../lib/content-reference';
  import {contentActivityExamples,contentActionLabels,contentConditionLabels,contentMotionLabels,type ContentActivityExample} from '../lib/content-preview';
  import {experienceError} from '../lib/experience';
  import example from '../../public/content-packs/desk-garden.json?raw';
  type Manifest={schemaVersion:1;id:string;version:number;name:string;author:string;license:string;runtimeVersion:1;dependencies:{id:string;minimumVersion:number}[];characters:{id:string;name:string;avatar:string;restPreference:number;sociability:number}[];objects:{id:string;name:string;kind:string;offers:string[]}[];motions:{id:string;capability:string;fallback:string}[];activities:{id:string;objectId:string;action:string;condition:string;weight:number;durationMs:number;motionId:string}[]};
  type Installed={manifest:Manifest;revision:number;active:boolean};
  type Preview={manifest:Manifest;resources:string[];warnings:string[];examples:ContentActivityExample[]};
  let {disabled=false,onCreated}:{disabled?:boolean;onCreated?:()=>Promise<void>}=$props();
  let source=$state(''),preview=$state<Preview>(),packs=$state<Installed[]>([]),pending=$state(false),error=$state(''),message=$state(''),previewSource=$state('');
  let alive=false;
  const uid=$props.id();
  function validatePreview(value:any):Preview{if(!value?.manifest||value.manifest.schemaVersion!==1||typeof value.manifest.id!=='string'||!Array.isArray(value.resources)||!['characters','objects','motions','activities','dependencies'].every(key=>Array.isArray(value.manifest[key])))throw Error('pack_invalid_schema');return {...value,examples:contentActivityExamples(value.manifest)};}
  async function refresh(){try{const value=await call<Installed[]>('list_content_packs');if(alive){if(!Array.isArray(value)||value.length>16)throw Error('pack_invalid_schema');packs=value;}}catch(e){if(alive)error=experienceError(e);}}
  async function readFile(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];preview=undefined;previewSource='';if(!file)return;if(file.size>128*1024){error='Das Paket ist zu groß.';return;}source=await file.text();error='';}
  async function inspect(){if(pending||disabled)return;pending=true;error='';message='';preview=undefined;const text=source;try{const value=validatePreview(await call('preview_content_pack',{manifestJson:text}));if(alive&&source===text){preview=value;previewSource=text;}}catch(e){if(alive)error=experienceError(e);}finally{if(alive)pending=false;}}
  async function install(){if(!preview||source!==previewSource||pending||disabled)return;pending=true;error='';try{packs=await call('install_content_pack',{manifestJson:previewSource});preview=undefined;previewSource='';message='Paket installiert. Aktiviere es anschließend ausdrücklich.';}catch(e){error=experienceError(e);}finally{pending=false;}}
  async function activation(pack:Installed){if(pending||disabled)return;pending=true;error='';try{packs=await call('set_content_pack_active',{packageId:pack.manifest.id,expectedRevision:pack.revision,active:!pack.active});message=pack.active?'Paket deaktiviert. Gespeicherte Verweise bleiben erhalten.':'Paket aktiviert. Life wird dadurch nicht gestartet.';}catch(e){error=experienceError(e);}finally{pending=false;}}
  async function remove(pack:Installed){if(pack.active||pending||disabled)return;pending=true;error='';try{packs=await call('delete_content_pack',{packageId:pack.manifest.id});}catch(e){error=experienceError(e);}finally{pending=false;}}
  async function createCharacter(pack:Installed,templateId:string){
    if(!pack.active||pending||disabled)return;pending=true;error='';message='';
    try{const reference=parseContentRef({packageId:pack.manifest.id,packageVersion:pack.manifest.version,templateId});
      const value:any=await call('create_content_pack_character',{reference});
      if(value?.version!==1||typeof value.botId!=='string'||!/^[A-Za-z0-9_-]{1,96}$/.test(value.botId))throw Error('pack_invalid_schema');
      if(alive)message='Neue Figur angelegt. Wähle sie in der Figurenliste und füge sie der Bühne hinzu. Sie wird dadurch nicht gestartet.';await onCreated?.();
    }catch(e){if(alive)error=experienceError(e);}finally{if(alive)pending=false;}
  }
  onMount(()=>{alive=true;void refresh();let stop=()=>{};void onEvent('content-packs-changed',()=>{if(!pending)void refresh();}).then(fn=>{if(alive)stop=fn;else fn();});return()=>{alive=false;stop();};});
</script>
<section class="settings-panel packs" aria-labelledby={`${uid}-title`}>
  <header><div><p class="eyebrow">{$t('Deklarative Inhalte')}</p><h2 id={`${uid}-title`}>{$t('Inhaltspakete')}</h2></div><button class="text-link" disabled={pending||disabled} onclick={refresh}>{$t('Neu laden')}</button></header>
  <p class="note">{$t('Charaktervorlagen, Objekte, Animation-Zuordnungen und Aktivitäten. Keine Skripte, externen Downloads oder zusätzlichen Rechte.')}</p>
  {#if error}<p class="error" role="alert">{$t(error)}</p>{/if}{#if message}<p class="note" role="status">{$t(message)}</p>{/if}
  <div class="import"><label for={`${uid}-file`}>{$t('Paketdatei · JSON, höchstens 128 KiB')}</label><input id={`${uid}-file`} type="file" accept="application/json,.json" disabled={pending||disabled} onchange={readFile}/><button class="text-link" disabled={pending||disabled} onclick={()=>{source=example;preview=undefined;previewSource='';error='';}}>{$t('Beispiel „Desk Garden“ laden')}</button><details open={!!source}><summary>{$t('Manifest ansehen')}</summary><label class="sr-only" for={`${uid}-json`}>{$t('Paketmanifest')}</label><textarea id={`${uid}-json`} spellcheck="false" rows="10" bind:value={source} oninput={()=>{preview=undefined;previewSource='';}} maxlength={128*1024} disabled={pending||disabled}></textarea></details><button class="button secondary" disabled={!native||!source||pending||disabled} onclick={inspect}>{$t('Prüfen & Vorschau')}</button></div>
  {#if preview}<section class="preview" aria-label={$t('Paketvorschau')}><header><div><h3>{preview.manifest.name} <small>v{preview.manifest.version}</small></h3><p class="note">{preview.manifest.author} · {preview.manifest.license}</p></div><span class="valid">{$t('Schema geprüft')}</span></header><dl><div><dt>{$t('Charaktere')}</dt><dd>{preview.manifest.characters.map(c=>c.name).join(', ')||'—'}</dd></div><div><dt>{$t('Objekte & Angebote')}</dt><dd>{preview.manifest.objects.map(o=>`${o.name} (${o.offers.length})`).join(', ')||'—'}</dd></div><div><dt>{$t('Animationszuordnungen')}</dt><dd>{formatNumber(preview.manifest.motions.length,$locale)}</dd></div><div><dt>{$t('Aktivitäten')}</dt><dd>{formatNumber(preview.manifest.activities.length,$locale)}</dd></div><div><dt>{$t('Ressourcen')}</dt><dd>{preview.resources.join(', ')||'—'}</dd></div><div><dt>{$t('Abhängigkeiten')}</dt><dd>{preview.manifest.dependencies.map(d=>`${d.id} ≥${d.minimumVersion}`).join(', ')||$t('Keine')}</dd></div></dl><details class="activity-examples" open><summary>{$t('Beispielhandlungen')}</summary>
    {#each preview.examples as activity(activity.id)}<article class="activity-example">
      <h4>{$t(contentActionLabels[activity.action])} · {activity.objectName}</h4>
      <dl><div><dt>{$t('Bedingung')}</dt><dd>{$t(contentConditionLabels[activity.condition])}</dd></div>
      <div><dt>{$t('Deklarierte Dauer')}</dt><dd>{$t('{seconds} Sekunden',{seconds:formatNumber(activity.durationMs/1000,$locale,{maximumFractionDigits:1})})}</dd></div>
      <div><dt>{$t('Deklarierte Bewegung')}</dt><dd>{$t(contentMotionLabels[activity.motion])}</dd></div>
      <div><dt>{$t('Erlaubter Ersatz')}</dt><dd>{$t(contentMotionLabels[activity.fallback])}</dd></div>
      <div><dt>{$t('Auswahlgewicht')}</dt><dd>{formatNumber(activity.weight,$locale)}</dd></div></dl>
      {#if activity.motion!=='idle'&&activity.fallback!=='idle'}<p class="note">{$t('Der aktuelle native Adapter benötigt einen Stillstehen-Fallback für diese Aktivität.')}</p>{/if}
    </article>{:else}<p class="note">{$t('Dieses Paket deklariert keine Aktivitäten.')}</p>{/each}
    <p class="note">{$t('Die Figur muss die Bewegung unterstützen. Die tatsächliche Mindestdauer berücksichtigt zusätzlich die Pflegeeinstellungen.')}</p>
  </details><p class="note">{$t('Die Vorschau führt nichts aus. Installation lässt das Paket zunächst deaktiviert.')}</p><button class="button primary" disabled={pending||disabled||source!==previewSource} onclick={install}>{$t('Geprüftes Paket installieren')}</button></section>{/if}
  <div class="installed"><h3>{$t('Lokal installierte Pakete')}</h3>{#if !packs.length}<p class="note">{$t('Noch keine Inhaltspakete installiert.')}</p>{:else}{#each packs as pack(pack.manifest.id)}<article><div><h4>{pack.manifest.name} <span>v{pack.manifest.version}</span></h4><p class="note">{pack.manifest.author} · {pack.manifest.license} · {$t(pack.active?'Aktiv':'Deaktiviert')}</p><small>{pack.manifest.id}</small>{#if pack.active&&pack.manifest.characters.length}<div class="template-actions">{#each pack.manifest.characters as character(character.id)}<button type="button" class="text-link" disabled={pending||disabled} onclick={()=>createCharacter(pack,character.id)}>{$t('Figur „{name}“ anlegen',{name:character.name})}</button>{/each}</div>{/if}</div><div class="actions"><button class="button secondary" disabled={pending||disabled} onclick={()=>activation(pack)}>{$t(pack.active?'Deaktivieren':'Ausdrücklich aktivieren')}</button><button class="text-link" disabled={pack.active||pending||disabled} onclick={()=>remove(pack)}>{$t('Löschen')}</button></div></article>{/each}{/if}</div>
  <p class="note">{$t('Aktualisierungen benötigen eine höhere Paketversion und vorherige Deaktivierung. Unbekannte Schemas werden abgewiesen; gespeicherte Verweise werden nicht umgeschrieben.')}</p>
</section>
<style>
.packs{margin-top:24px}header{display:flex;align-items:center;justify-content:space-between;gap:16px}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:10px;color:var(--muted);margin:0 0 5px}h2{font-size:20px;margin:0}h3{font-size:14px}h4{font-size:13px;margin:0}h4 span,h3 small{font-weight:400;color:var(--muted)}.note{font-size:12px;color:var(--muted);line-height:1.7}.import{display:grid;justify-items:start;gap:12px;padding:20px 0;border-bottom:1px solid var(--line)}.import>label{font-size:12px}.import input{font-size:12px}.import details{width:100%}summary{cursor:pointer;font-size:12px}textarea{width:100%;font-family:monospace;font-size:12px;resize:vertical;margin:10px 0}.preview{padding:20px 0;border-bottom:1px solid var(--line)}.activity-examples{margin:16px 0}.activity-examples>summary{font-weight:600}.activity-example{margin-top:12px;padding:16px;border:1px solid var(--line);border-radius:12px}.activity-example dl{margin-bottom:0}.valid{font-size:11px;color:var(--accent)}dl{font-size:12px}dl>div{display:grid;grid-template-columns:170px 1fr;gap:12px;padding:8px 0}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}.installed article{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:16px 0;border-bottom:1px solid var(--line)}.installed small{font-size:10px;color:var(--muted)}.template-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:12px}.actions{display:flex;gap:12px;align-items:center}.error{font-size:12px;color:var(--danger)}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:680px){.installed article{align-items:start;flex-direction:column}.actions{flex-wrap:wrap}dl>div{grid-template-columns:1fr;gap:4px}}
</style>
